/*
 * A040579  Continued fraction for sqrt(604).
 * https://oeis.org/A040579
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy, less
 * Formula:   a(n) is the nth term of the continued fraction expansion of
 *            sqrt(604). The expansion is generated by the standard recurrence
 *            for quadratic irrationals: Let a0 = floor(sqrt(604)) = 24. Set
 *            m0 = 0, d0 = 1, a0 = 24. For k ≥ 0: m_{k+1} = d_k * a_k - m_k
 *            d_{k+1} = (604 - m_{k+1}^2) / d_k a_{k+1} = (a0...
 * Range:     u8 none, u16 n <= 88, u32 n <= 88, u64 n <= 88, u128 n <= 88,
 *            big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include "../utils/floor_sqrt.h"

seq_t a(idx_t n)
{
    const seq_t D   = 604;                 /* The radicand */
    const seq_t a0  = floor_sqrt(D);       /* a0 = floor(sqrt(D)) = 24 */

    if (n == 0)
        return a0;

    seq_t m = 0;
    seq_t d = 1;
    seq_t a_val = a0;                      /* Current continued‑fraction term */

    for (idx_t k = 1;; ++k) {
        /* compute next triple (m, d, a_val) */
        m = d * a_val - m;
        d = (D - m * m) / d;
        a_val = (a0 + m) / d;

        if (k == n)
            return a_val;
    }
}
